pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  var best: Map[Int, Int] = Map {}
  best = best.set(src, 0)
  for _k in range(0, n) {
    for e in edges {
      let u = e.get_or(0, 0)
      let v = e.get_or(1, 0)
      let w = e.get_or(2, 0)
      if best.has(u) {
        let cand = best.get(u).unwrap_or(0) + w
        let improves = match best.has(v) {
          true => cand < best.get(v).unwrap_or(0),
          false => true,
        }
        if improves {
          best = best.set(v, cand)
        }
      }
    }
  }
  let done_map = best
  return range(0, n).map(fn(i) => done_map.get(i).unwrap_or(-1))
}
